/**
 * Room codes: 8 symbols from a 31-character alphabet with look-alikes removed
 * (no 0/O, 1/I/L). ~39.6 bits of entropy; the backend additionally rate-limits
 * join attempts so codes can't be enumerated.
 *
 * The client only normalises and validates format. Codes are generated by the
 * server (the mock server uses `generateRoomCode` below).
 */
export const ROOM_CODE_ALPHABET = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";
export const ROOM_CODE_LENGTH = 8;

export function normalizeRoomCode(input: string): string {
  return input.toUpperCase().replace(/[\s-]/g, "");
}

export function isValidRoomCode(input: string): boolean {
  const code = normalizeRoomCode(input);
  if (code.length !== ROOM_CODE_LENGTH) return false;
  for (const ch of code) if (!ROOM_CODE_ALPHABET.includes(ch)) return false;
  return true;
}

/** "ABCD2345" -> "ABCD-2345" for display and reading aloud. */
export function formatRoomCode(code: string): string {
  const c = normalizeRoomCode(code);
  return c.length === ROOM_CODE_LENGTH ? `${c.slice(0, 4)}-${c.slice(4)}` : c;
}

export function generateRoomCode(randomValues: (arr: Uint32Array) => Uint32Array = (a) => crypto.getRandomValues(a)): string {
  const bytes = randomValues(new Uint32Array(ROOM_CODE_LENGTH));
  let out = "";
  for (const n of bytes) out += ROOM_CODE_ALPHABET[n % ROOM_CODE_ALPHABET.length];
  return out;
}
